    .sectionHeader{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:10px}.sectionTitle{font-size:17px;font-weight:760}.clear{background:none;color:var(--accent);font-size:13px;padding:5px}.history{border:1px solid rgba(127,168,184,.16);border-radius:16px;overflow:hidden;min-width:0}.historyItem{width:100%;min-width:0;display:grid;grid-template-columns:38px minmax(0,1fr) 20px;align-items:center;gap:10px;padding:11px 12px;background:rgba(3,8,12,.56);border-bottom:1px solid rgba(127,168,184,.12);cursor:pointer}.historyItem:last-child{border-bottom:0}.historyIcon{width:34px;height:34px;border-radius:10px;display:grid;place-items:center;color:var(--accent);background:rgba(23,184,187,.055);border:1px solid rgba(23,184,187,.12)}.historyText{min-width:0;overflow:hidden}.historyName{font-size:13px;font-weight:650;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.historyMeta{font-size:11px;color:#77838f;margin-top:3px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.chev{color:#667580;font-size:20px;text-align:right}.empty{font-size:13px;color:#71808c;padding:13px}.pairSummary{display:flex;align-items:center;gap:9px;color:#8e9aa6;font-size:12px;margin-top:10px}.shield{color:var(--accent)}.pairFields{margin-top:12px}.pairActions{display:grid;grid-template-columns:1fr auto;gap:9px;margin-top:10px}.tiny{font-size:10px;color:#596570;margin:22px auto 0;text-align:center;line-height:1.55;max-width:480px;padding:0 8px}.tiny strong{color:#7d8994;font-weight:650}
