<body><main>
  <div class="topbar">
    <button id="howToBtn" class="topBtn" type="button">? <span data-i18n="howTo">How-to</span></button>
    <select id="lang" class="langSelect" aria-label="Language"><option value="en">EN</option><option value="ro">RO</option><option value="fr">FR</option><option value="de">DE</option></select>
    <button id="beerBtn" class="topBtn beer" type="button">🍺 <span data-i18n="beer">Offer me a beer</span></button>
  </div>
  <header class="brand"><img class="brandMark" src="/icon-512.png?v=0240" alt="Flud Companion"><div class="brandLine"><strong>Flud</strong><span>Companion</span></div><div class="maker">alexlab.media</div><div class="version">Bridge $version</div><div class="platform" data-i18n="crossPlatform">Cross-platform · iPhone · Android · Tablet · Desktop</div></header>
  <div class="mode"><span data-i18n="remote">Remote</span><span class="active">LAN</span></div>
  <section class="card"><div class="row"><div class="statusWrap"><div class="deviceIcon">↔</div><div><div class="eyebrow" data-i18n="androidDevice">Android device</div><div class="status"><span id="dot" class="dot"></span><span id="state"></span></div></div></div><button id="refresh" class="iconButton">↻ <span data-i18n="refresh">Refresh</span></button></div><div id="detail" class="muted detail"></div></section>
