  <section class="card"><div class="sectionHeader"><div><div class="sectionTitle" data-i18n="recent">Recent sends</div><div class="muted" data-i18n="storedBrowser">Stored only in this browser</div></div><button id="clearHistory" class="clear" data-i18n="clear">Clear</button></div><div id="history" class="history"></div></section>
