  };
  var langKey='fludCompanionLang',tokenKey='fludRemoteLanToken',autoKey='fludRemoteLanAutoStartV1',historyKey='fludRemoteLanHistoryV1',sendCountKey='fludCompanionSuccessfulSendCountV1';
  var langSelect=document.getElementById('lang'),token=document.getElementById('token'),state=document.getElementById('state'),dot=document.getElementById('dot'),detail=document.getElementById('detail'),message=document.getElementById('message'),magnet=document.getElementById('magnet'),autoStart=document.getElementById('autoStart'),autoHint=document.getElementById('autoHint'),historyEl=document.getElementById('history');var helperReady=false;
  function initialLang(){var saved=localStorage.getItem(langKey);if(I18N[saved])return saved;var n=(navigator.language||'en').slice(0,2).toLowerCase();return I18N[n]?n:'en'}var lang=initialLang();
  function t(k){return (I18N[lang]&&I18N[lang][k])||I18N.en[k]||k}
  function applyLang(){document.documentElement.lang=lang;langSelect.value=lang;document.querySelectorAll('[data-i18n]').forEach(function(el){el.textContent=t(el.getAttribute('data-i18n'))});document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){el.placeholder=t(el.getAttribute('data-i18n-placeholder'))});renderHistory();updateAutoHint();status()}
  token.value=localStorage.getItem(tokenKey)||'';autoStart.checked=localStorage.getItem(autoKey)==='1';
  function modal(id,show){document.getElementById(id).classList.toggle('show',show)}document.querySelectorAll('[data-close]').forEach(function(b){b.onclick=function(){modal(b.getAttribute('data-close'),false)}});document.getElementById('howToBtn').onclick=function(){modal('howToModal',true)};document.getElementById('beerBtn').onclick=function(){modal('beerModal',true)};document.querySelectorAll('.modal').forEach(function(m){m.addEventListener('click',function(e){if(e.target===m)modal(m.id,false)})});langSelect.onchange=function(){lang=langSelect.value;localStorage.setItem(langKey,lang);applyLang()};
  function consumePairingFragment(){try{var hash=(location.hash||'').replace(/^#/,'');if(!hash)return false;var q=new URLSearchParams(hash),v=(q.get('token')||'').trim();if(v.length<20)return false;token.value=v;localStorage.setItem(tokenKey,v);history.replaceState(null,'',location.pathname+location.search);show(t('pairedQr'),true);return true}catch(e){return false}}
  function auth(){return {'Authorization':'Bearer '+token.value.trim()}}function show(text,ok){message.textContent=text||'';message.className='msg '+(ok?'ok':'err')}function info(text){message.textContent=text||'';message.className='msg info'}function historyList(){try{return JSON.parse(localStorage.getItem(historyKey)||'[]')||[]}catch(e){return []}}function magnetName(value){try{var q=new URLSearchParams(value.split('?').slice(1).join('?'));return q.get('dn')||q.get('xt')||'Magnet'}catch(e){return 'Magnet'}}function addHistory(value,withAuto){var list=historyList().filter(function(x){return x.magnet!==value});list.unshift({magnet:value,name:magnetName(value),autoStart:!!withAuto,at:Date.now()});localStorage.setItem(historyKey,JSON.stringify(list.slice(0,12)));renderHistory()}function maybeSupportReminder(){try{var n=parseInt(localStorage.getItem(sendCountKey)||'0',10);if(!Number.isFinite(n)||n<0)n=0;n+=1;localStorage.setItem(sendCountKey,String(n));if(n%50===0)setTimeout(function(){modal('supportReminderModal',true)},350)}catch(e){}}
  function renderHistory(){if(!historyEl)return;var list=historyList();historyEl.innerHTML='';if(!list.length){historyEl.innerHTML='<div class="empty">'+t('noHistory')+'</div>';return}list.forEach(function(item){var row=document.createElement('div');row.className='historyItem';row.setAttribute('role','button');row.tabIndex=0;var icon=document.createElement('div');icon.className='historyIcon';icon.textContent='▤';var txt=document.createElement('div');txt.className='historyText';var name=document.createElement('div');name.className='historyName';name.textContent=item.name||'Magnet';var meta=document.createElement('div');meta.className='historyMeta';meta.textContent=new Date(item.at||Date.now()).toLocaleString(lang)+(item.autoStart?' · '+t('autoTag'):'');var chev=document.createElement('div');chev.className='chev';chev.textContent='›';txt.appendChild(name);txt.appendChild(meta);row.appendChild(icon);row.appendChild(txt);row.appendChild(chev);function again(){magnet.value=item.magnet;autoStart.checked=!!item.autoStart;localStorage.setItem(autoKey,autoStart.checked?'1':'0');updateAutoHint();send()}row.onclick=again;row.onkeydown=function(e){if(e.key==='Enter'||e.key===' '){e.preventDefault();again()}};historyEl.appendChild(row)})}
  function updateAutoHint(){if(autoStart.checked&&!helperReady){autoHint.textContent=t('autoEnable');autoHint.className='toggleHint warning'}else if(autoStart.checked){autoHint.textContent=t('autoReadyText');autoHint.className='toggleHint'}else{autoHint.textContent=t('autoOptional');autoHint.className='toggleHint'}}
  async function status(){if(!token.value.trim()){helperReady=false;state.textContent=t('notPaired');dot.className='dot';detail.textContent=t('saveLan');updateAutoHint();return}try{var r=await fetch('/api/v1/status',{headers:auth(),cache:'no-store'}),j=await r.json();if(!r.ok)throw new Error(j.error||('HTTP '+r.status));helperReady=!!(j.autoStartHelper||j.remoteAutoStartHelper);state.textContent=t('online');dot.className='dot on';detail.textContent=t('bridge')+' '+(j.version||'?')+' · '+(j.cloudEnabled?t('remoteEnabled'):t('lanReady'))+' · '+(helperReady?t('autoReady'):t('autoOff'));updateAutoHint()}catch(e){helperReady=false;state.textContent=t('unavailable');dot.className='dot off';detail.textContent=e.message||String(e);updateAutoHint()}}
  async function send(){var value=magnet.value.trim();if(!value.toLowerCase().startsWith('magnet:?')){show(t('validMagnet'),false);return}if(autoStart.checked&&!helperReady){show(t('autoMissing'),false);return}show(autoStart.checked?t('sendingAuto'):t('sending'),true);try{var r=await fetch('/api/v1/magnet',{method:'POST',headers:Object.assign({'Content-Type':'application/json'},auth()),body:JSON.stringify({magnet:value,autoStart:autoStart.checked})}),j=await r.json();if(!r.ok)throw new Error(j.error||('HTTP '+r.status));addHistory(value,autoStart.checked);maybeSupportReminder();show(autoStart.checked?t('sentAuto'):t('sent'),true);magnet.value='';await status()}catch(e){show(e.message||String(e),false)}}
  async function pasteMagnet(){if(window.isSecureContext&&navigator.clipboard&&navigator.clipboard.readText){try{magnet.value=await navigator.clipboard.readText();show(t('pasted'),true);return}catch(e){}}magnet.focus();try{magnet.setSelectionRange(magnet.value.length,magnet.value.length)}catch(e){}info(t('clipboardBlocked'))}
  document.getElementById('save').onclick=function(){localStorage.setItem(tokenKey,token.value.trim());show(t('pairSaved'),true);status()};document.getElementById('forget').onclick=function(){localStorage.removeItem(tokenKey);token.value='';show(t('pairRemoved'),true);status()};document.getElementById('refresh').onclick=status;document.getElementById('send').onclick=send;document.getElementById('paste').onclick=pasteMagnet;document.getElementById('clearHistory').onclick=function(){localStorage.removeItem(historyKey);renderHistory()};autoStart.onchange=function(){localStorage.setItem(autoKey,autoStart.checked?'1':'0');updateAutoHint()};consumePairingFragment();applyLang();
})();
</script></body></html>
